"""Core pinning functionality for tessaro-feeds."""

import hashlib
import base64
import importlib.resources


class PinStore:
    """A store of certificate fingerprints pinned to hostnames."""

    def __init__(self, pins: dict):
        self._pins = pins

    @classmethod
    def load(cls) -> "PinStore":
        """Load the pin store from the bundled pins data."""
        pins = {}
        pins_path = importlib.resources.files(__package__) / "pins.json"
        with importlib.resources.as_file(pins_path) as f:
            import json
