                data = json.load(fh)
        for entry in data:
            pins[entry["host"]] = entry["fingerprint"]
        return cls(pins)

    def matches(self, host: str, fingerprint: str) -> bool:
        """Return True if `fingerprint` matches the pinned fingerprint for `host`."""
        return self._pins.get(host) == fingerprint


